static bool get_glyph_dsc_ui_18(const lv_font_t *font, lv_font_glyph_dsc_t *dsc_out, uint32_t letter, uint32_t letter_next)
{
    (void)letter_next;
    const ui_custom_glyph_t *g = NULL;
    if (letter >= 32 && letter <= 126) {
        g = &s_glyphs_18_ascii[letter - 32];
    } else {
        for (size_t i = 0; i < sizeof(s_glyphs_18_unicode)/sizeof(s_glyphs_18_unicode[0]); i++) {
            if (s_glyphs_18_unicode[i].unicode == letter) {
                g = &s_glyphs_18_unicode[i];
                break;
            }
        }
    }
    if (!g || (g->box_w == 0 && g->adv_w == 0)) return false;

    dsc_out->adv_w = g->adv_w;
    dsc_out->box_w = g->box_w;
    dsc_out->box_h = g->box_h;
    dsc_out->ofs_x = g->ofs_x;
    dsc_out->ofs_y = g->ofs_y;
    dsc_out->bpp = 4;
    dsc_out->is_placeholder = 0;
    dsc_out->resolved_font = font;
    return true;
}

static const uint8_t *get_glyph_bitmap_ui_18(const lv_font_t *font, uint32_t letter)
{
    (void)font;
    if (letter >= 32 && letter <= 126) {
        return s_glyphs_18_ascii[letter - 32].bitmap;
    }
    for (size_t i = 0; i < sizeof(s_glyphs_18_unicode)/sizeof(s_glyphs_18_unicode[0]); i++) {
        if (s_glyphs_18_unicode[i].unicode == letter) {
            return s_glyphs_18_unicode[i].bitmap;
        }
    }
    return NULL;
}

